gTH(){return"\u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0623\u064a\u0636\u064b\u0627 \u0644\u0643\u0644 \u062d\u062f\u0648\u062f \u062c\u062f\u0648\u0644/\u0645\u0631\u0628\u0639 \u0641\u064a \u0645\u0633\u062a\u0646\u062f\u0627\u062a\u0643 \u0627\u0644\u0645\u0637\u0628\u0648\u0639\u0629 \u2014 \u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0637\u0628\u0627\u0639\u0629 \u0646\u0641\u0633\u0647 \u0644\u0627 \u064a\u062a\u063a\u064a\u0631 \u0623\u0628\u062f\u064b\u0627\u060c \u0641\u0642\u0637 \u0647\u0630\u0627 \u0627\u0644\u0644\u0648\u0646."},
gHA(){return"\u0644\u0648\u0646 \u0646\u0635 \u0627\u0644\u0645\u0633\u062a\u0646\u062f"},
