On(a){return"\u062a\u0645\u062a \u0625\u0632\u0627\u0644\u0629 "+a+"."},
Om(a,b){return"\u062a\u0639\u0630\u0631\u062a \u0625\u0632\u0627\u0644\u0629 "+a+": "+b},
gFu(){return"\u0625\u0632\u0627\u0644\u0629"},
gOe(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0647\u0627\u062a\u0641"},
gOr(){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0627\u0644\u0631\u0642\u0645 \u0627\u0644\u0633\u0631\u064a"},
gO7(){return"\u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0645\u062f\u064a\u0631"},
gO6(){return"\u064a\u0645\u0643\u0646\u0647 \u062a\u0639\u062f\u064a\u0644 \u0648\u062d\u0630\u0641 \u0627\u0644\u0641\u0648\u0627\u062a\u064a\u0631 \u0648\u0627\u0644\u0645\u0634\u062a\u0631\u064a\u0627\u062a \u0648\u0627\u0644\u0633\u0646\u062f\u0627\u062a \u0627\u0644\u0645\u064f\u0631\u062d\u0651\u0644\u0629 \u2014 \u0639\u0627\u062f\u0629\u064b \u0644\u0644\u0645\u0627\u0644\u0643 \u0641\u0642\u0637."},
